parameters.jsCode:
// Code node — "Build HTML Report"
const reportItem = $('Set Gemini Output Fields').item.json;

// Base64 string now comes from "Extract from File" node's JSON output
const base64Raw = $input.first().json.data;

if (!base64Raw) {
  throw new Error('No base64 data found on input — check "Extract from File" node output.');
}

// Defensive cleanup: strip whitespace/newlines and any accidental
// existing "data:...;base64," prefix before rebuilding the URI
let base64 = base64Raw.trim();
base64 = base64.replace(/^data:.*;base64,/, '');

const mimeType = 'image/png'; // QuickChart always returns PNG here
const imgSrc = `data:${mimeType};base64,${base64}`;

// Sanity checks — throws loudly instead of silently producing a broken image
if (base64.length < 100) {
  throw new Error(`Base64 payload looks too short (${base64.length} chars) — this is not a valid image.`);
}
if (!/^[A-Za-z0-9+/=]+$/.test(base64)) {
  throw new Error('Base64 payload contains invalid characters — data may be corrupted or wrong field was read.');
}

console.log('Base64 length:', base64.length);
console.log('img tag preview:', `<img src="data:${mimeType};base64,${base64.slice(0, 40)}...`);

const markdownToHtml = reportItem.report_json.markdown_report
  .replace(/^## (.*)$/gm, '<h2>$1</h2>')
  .replace(/\n\n/g, '<br><br>');

const html = `<html><head><meta charset="utf-8"><style>
body{font-family:Arial,sans-serif;margin:40px;color:#222}
h1{color:#2E86AB;border-bottom:2px solid #2E86AB;padding-bottom:8px}
h2{color:#333;margin-top:28px}
img{margin-top:16px}
</style></head><body>
<h1>Due Diligence Report: ${reportItem.company_name}</h1>
<p><em>Domain: ${reportItem.company_domain} — Generated ${new Date().toISOString().slice(0,10)}</em></p>
${markdownToHtml}
<h2>Tech Maturity Chart</h2>
<img src="${imgSrc}" width="500"/>
</body></html>`;

return [{ json: { html } }];

